import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi } from 'vitest';
import { BookCard } from './BookCard';
import type { Book } from '../../types';

const baseBook: Book = {
  id: 'book-1',
  title: 'The Great Gatsby',
  author: 'F. Scott Fitzgerald',
  status: 'available',
};

describe('BookCard', () => {
  it('renders the book title', () => {
    render(<BookCard book={baseBook} onClick={vi.fn()} />);
    expect(screen.getByRole('heading', { name: 'The Great Gatsby' })).toBeInTheDocument();
  });

  it('renders the book author', () => {
    render(<BookCard book={baseBook} onClick={vi.fn()} />);
    expect(screen.getByText('F. Scott Fitzgerald')).toBeInTheDocument();
  });

  it('renders the status badge with the book status text', () => {
    render(<BookCard book={baseBook} onClick={vi.fn()} />);
    expect(screen.getByText('available')).toBeInTheDocument();
  });

  it('sets data-status attribute on the badge to the book status', () => {
    render(<BookCard book={{ ...baseBook, status: 'checked-out' }} onClick={vi.fn()} />);
    const badge = screen.getByText('checked-out');
    expect(badge).toHaveAttribute('data-status', 'checked-out');
  });

  it('sets aria-label combining title and author', () => {
    render(<BookCard book={baseBook} onClick={vi.fn()} />);
    expect(
      screen.getByRole('button', { name: 'The Great Gatsby by F. Scott Fitzgerald' })
    ).toBeInTheDocument();
  });

  it('calls onClick with the book id when clicked', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={baseBook} onClick={handleClick} />);
    await userEvent.click(screen.getByRole('button'));
    expect(handleClick).toHaveBeenCalledOnce();
    expect(handleClick).toHaveBeenCalledWith('book-1');
  });

  it('calls onClick with the book id when Enter is pressed', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={baseBook} onClick={handleClick} />);
    screen.getByRole('button').focus();
    await userEvent.keyboard('{Enter}');
    expect(handleClick).toHaveBeenCalledOnce();
    expect(handleClick).toHaveBeenCalledWith('book-1');
  });

  it('does not call onClick when a non-Enter key is pressed', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={baseBook} onClick={handleClick} />);
    screen.getByRole('button').focus();
    await userEvent.keyboard('{Space}');
    expect(handleClick).not.toHaveBeenCalled();
  });

  it('renders different statuses correctly', () => {
    const { rerender } = render(<BookCard book={baseBook} onClick={vi.fn()} />);
    expect(screen.getByText('available')).toBeInTheDocument();

    rerender(<BookCard book={{ ...baseBook, status: 'reserved' }} onClick={vi.fn()} />);
    expect(screen.getByText('reserved')).toBeInTheDocument();
  });
});

