import { renderHook, waitFor } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { useBooks } from './useBooks';
import * as api from '../api';

describe('useBooks', () => {
  const mockBooks = [
    { id: '1', title: 'Dune', author: 'Frank Herbert', status: 'available' as const },
    { id: '2', title: '1984', author: 'George Orwell', status: 'checked-out' as const },
  ];

  beforeEach(() => {
    vi.restoreAllMocks();
  });

  it('starts in the loading state', () => {
    vi.spyOn(api, 'getBooks').mockReturnValue(new Promise(() => {})); // never resolves
    const { result } = renderHook(() => useBooks());
    expect(result.current.loading).toBe(true);
    expect(result.current.data).toBeNull();
    expect(result.current.error).toBeNull();
  });

  it('transitions to data state on success', async () => {
    vi.spyOn(api, 'getBooks').mockResolvedValue(mockBooks);
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.data).toEqual(mockBooks);
    expect(result.current.error).toBeNull();
  });

  it('transitions to error state on failure', async () => {
    vi.spyOn(api, 'getBooks').mockRejectedValue(new Error('fetch failed'));
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.error).toBeInstanceOf(Error);
    expect(result.current.data).toBeNull();
  });

  it('returns an empty array when getBooks resolves with no books', async () => {
    vi.spyOn(api, 'getBooks').mockResolvedValue([]);
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.data).toEqual([]);
    expect(result.current.error).toBeNull();
  });

  it('calls getBooks exactly once on mount', async () => {
    const spy = vi.spyOn(api, 'getBooks').mockResolvedValue(mockBooks);
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(spy).toHaveBeenCalledOnce();
  });
});
```

**Key decisions:**
- Spies on `api.getBooks` at the module boundary — no mock of the hook's internals
- Tests the three state transitions: `loading → data`, `loading → error`, `loading → empty data`
- Pins the invariant that loading starts `true` and ends `false` in both success and error paths
- `waitFor` handles the async state settlement without manual `act()` wrapping for simple cases

